-- SAMPLE ONLY -- NOT the full dataset. A 125-row API slice; NSF Award Search covers roughly 500,000 awards. Use for shape/testing, never for funding-coverage claims. Labeled 2026-08-11 (verification sweep, defect class 7).
-- Source: NSF Award Search API (125 rows)
-- Generated by gen_mart_models.py

-- DEDUP (2026-08-18 verification): 10 duplicate groups, every one exactly size 2,
-- single load run (1 distinct _SOURCE_RUN_ID) -- consistent with an overlapping-
-- window double-fetch in this one-off 125-row API test pull. Live: 125 rows / 115
-- distinct -- single-load duplication, exact dups carry no information. Low
-- stakes given the source is already documented above as a non-authoritative
-- sample.
with source as (
    select * from {{ source('ripple_raw', 'FED_NSF_AWARDS') }}
    qualify row_number() over (
        partition by AWARD_ID, TITLE, AWARDEE_NAME, INSTITUTION, PI_NAME,
                     CO_PI_NAMES, PROGRAM_OFFICER, AWARD_AMOUNT, AWARD_DATE,
                     START_DATE, END_DATE, STATUS, ABSTRACT, PROGRAM_NAME, EIN,
                     ZIP, CITY, STATE, COUNTRY, CFDA_NUMBER
        order by _INGESTED_AT) = 1
)

select
    AWARD_ID as award_id,
    TITLE as title,
    AWARDEE_NAME as awardee_name,
    INSTITUTION as institution,
    PI_NAME as pi_name,
    CO_PI_NAMES as co_pi_names,
    PROGRAM_OFFICER as program_officer,
    try_to_double(AWARD_AMOUNT) as award_amount,
    try_to_date(AWARD_DATE) as award_date,
    try_to_date(START_DATE) as start_date,
    try_to_date(END_DATE) as end_date,
    STATUS as status,
    ABSTRACT as abstract,
    PROGRAM_NAME as program_name,
    EIN as ein,
    ZIP as zip,
    CITY as city,
    STATE as state,
    COUNTRY as country,
    CFDA_NUMBER as cfda_number
from source
